// ❌ BEFORE: Long synchronous loop freezes main thread
function processHeavyFilters(items) {
  for (const item of items) {
    calculatePriceMatrix(item); // 280ms total freeze
  }
  updateDOM();
}

// ✅ AFTER: Yield main thread to allow browser frame paint
async function processHeavyFilters(items) {
  for (const item of items) {
    calculatePriceMatrix(item);
    if ('scheduler' in window && scheduler.yield) {
      await scheduler.yield(); // Lets user clicks & paints breathe
    }
  }
  updateDOM();
}

// ✅ Laravel 11 Redis Middleware: Sub-30ms Response
namespace App\Http\Middleware;

use Illuminate\Support\Facades\Redis;

class CacheResponseWithRedis {
    public function handle($request, \Closure $next) {
        if ($request->isMethod('GET') && !auth()->check()) {
            $key = 'page:' . sha1($request->fullUrl());
            if ($cached = Redis::get($key)) {
                return response($cached)->header('X-Cache-Engine', 'Redis-RAM');
            }
            $response = $next($request);
            Redis::setex($key, 3600, $response->getContent());
            return $response;
        }
        return $next($request);
    }
}
